async function fetchDataFromApiCall(autocomplete, searchTerm) {
    const result = await fetch(
        `https://geo.api.vlaanderen.be/geolocation/suggestion?q=${searchTerm}&c=${autocomplete.maxSuggestions}`
    );
    const responseBody = await result.json();
    // matches toont de suggesties en zet de laadindicator uit.
    autocomplete.matches = responseBody.SuggestionResult.map((obj) => ({
        title: obj,
        value: obj,
    }));
}

// search volgt zodra de gebruiker minstens min-chars tekens typt en de component geen items heeft.
document.querySelector('vl-autocomplete').addEventListener('search', (event) => {
    fetchDataFromApiCall(event.target, event.detail.searchTerm);
});

// Typ 'Drab' om de resultaten te zien.
async function mockedApiCall(searchTerm, maxSuggestions) {
    const results = [
        'Drabbinkdreef, Gent',
        'Drabstraat, Gent',
        'Drabstraat, Kontich',
        'Drabstraat, Mechelen',
        'Drabstraat, Mortsel',
        'Drabstraat, Wichelen',
        'Drabstraat, Zwevezele',
    ];
    const filteredResults = results
        .filter((i) => i.toLowerCase().startsWith(searchTerm.toLowerCase()))
        .slice(0, maxSuggestions);
    return {
        SuggestionResult: filteredResults,
    };
}

async function fetchDataFromMockedApiCall(autocomplete, searchTerm) {
    const responseBody = await mockedApiCall(searchTerm, autocomplete.maxSuggestions);
    autocomplete.matches = responseBody.SuggestionResult.map((obj) => ({
        title: obj,
        value: obj,
    }));
}

document.querySelector('vl-autocomplete').addEventListener('search', (event) => {
    fetchDataFromMockedApiCall(event.target, event.detail.searchTerm);
});

